<div class="section-heading"><div><div class="eyebrow">Acessos</div><h1>Editar usuário</h1><p class="text-secondary mb-0"><?=htmlspecialchars($account['tenant_name']??'Equipe da plataforma')?></p></div><a class="btn btn-light" href="/master/users">Voltar</a></div><div class="card mb-4"><div class="card-body"><form method="post" action="/master/users/<?=(int)$account['id']?>/update"><?php echo \App\Core\CSRF::field();?><div class="row g-3"><div class="col-md-5"><label class="form-label">Nome</label><input class="form-control" name="name" value="<?=htmlspecialchars($account['name'],ENT_QUOTES,'UTF-8')?>" required></div><div class="col-md-4"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email" value="<?=htmlspecialchars($account['email'],ENT_QUOTES,'UTF-8')?>" required></div><div class="col-md-3"><label class="form-label">Perfil</label><select class="form-select" name="role"><?php foreach($roles as $slug=>$label):?><option value="<?=$slug?>" <?=$account['role_slug']===$slug?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active'=>'Ativo','pending'=>'Pendente','inactive'=>'Inativo'] as $v=>$l):?><option value="<?=$v?>" <?=$account['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><div class="form-text">Para bloqueio de segurança/administrativo, use a ação Bloquear na listagem.</div></div></div><button class="btn btn-primary mt-4">Salvar alterações</button></form></div></div><?php if($account['tenant_id']===null&&$account['role_slug']==='commercial'):?><div class="card"><div class="card-header"><strong>Regras do Comercial</strong></div><div class="card-body"><form method="post" action="/master/users/<?=(int)$account['id']?>/comercial" class="row g-3"><?=\App\Core\CSRF::field()?><div class="col-md-4"><label class="form-label">Comissão sobre o primeiro pagamento (%)</label><input class="form-control" type="number" min="0" max="100" step=".01" name="commission_percent" value="<?=htmlspecialchars((string)($account['commission_percent']??0))?>" required></div><div class="col-md-4"><label class="form-label">Desconto máximo permitido (%)</label><input class="form-control" type="number" min="0" max="100" step=".01" name="max_discount_percent" value="<?=htmlspecialchars((string)($account['max_discount_percent']??0))?>" required></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-primary w-100">Salvar regras comerciais</button></div></form></div></div><?php endif;?>
